import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.BEUshCVJ.js";const m=JSON.parse('{"title":"实机测试清单","description":"","frontmatter":{},"headers":[],"relativePath":"zh/test-checklist.md","filePath":"zh/test-checklist.md","lastUpdated":1792982537000}'),o={name:"zh/test-checklist.md"};function r(s,e,n,h,c,d){return l(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="实机测试清单" tabindex="-1">实机测试清单 <a class="header-anchor" href="#实机测试清单" aria-label="Permalink to &quot;实机测试清单&quot;">​</a></h1><p>本页列出只能在真实 Windows 电脑上完成的检查：音频、快捷键、面板、语音合成和真实供应商延迟。其余部分由自动化测试覆盖。每次发布前，用 <code>scoop install meetcue</code> 安装后逐项检查。</p><p>某项未通过时，记下错误码（如有），<a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="先运行自检" tabindex="-1">先运行自检 <a class="header-anchor" href="#先运行自检" aria-label="Permalink to &quot;先运行自检&quot;">​</a></h2><ul><li>[ ] <code>MeetCue.exe --version</code> 输出预期的版本号。</li><li>[ ] 将扬声器静音或戴上耳机，运行 <code>MeetCue.exe --self-test</code>，所有项目都显示通过。</li></ul><h2 id="设置与演示" tabindex="-1">设置与演示 <a class="header-anchor" href="#设置与演示" aria-label="Permalink to &quot;设置与演示&quot;">​</a></h2><ul><li>[ ] 首次启动出现设置向导；填入语音识别和模型密钥后，延迟探测给出结果表和组合排名。</li><li>[ ] <code>MeetCue.exe --demo</code> 能完整播放示例面试。</li></ul><h2 id="音频" tabindex="-1">音频 <a class="header-anchor" href="#音频" aria-label="Permalink to &quot;音频&quot;">​</a></h2><ul><li>[ ] 播放视频时“系统声音”电平条跳动；对着麦克风说话时“麦克风”电平条跳动。</li><li>[ ] 使用外放而不是耳机时，对方的话不会被当成你说的。</li><li>[ ] 拔插耳机或切换默认设备后，采集自动恢复。</li></ul><h2 id="会议" tabindex="-1">会议 <a class="header-anchor" href="#会议" aria-label="Permalink to &quot;会议&quot;">​</a></h2><ul><li>[ ] 真实会议中，对方问完问题约 1.5 秒内出现问题块和要点，底栏延迟数字与之相符。</li><li>[ ] 回答时，讲到的要点打勾，下一条高亮。</li><li>[ ] 你回答时对方插话提问，新问题进入 <strong>下一问</strong>，当前提示不被替换。</li><li>[ ] 五个快捷键全部生效；会议软件自己的快捷键（如 Teams 的 <code>Ctrl+Shift+M</code>）仍然正常。</li><li>[ ] 点击面板不会让会议窗口失去焦点。</li><li>[ ] 共享整个屏幕时，对方看不到面板。</li></ul><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><ul><li>[ ] 用示例字幕和示例问题列表各练一轮。</li><li>[ ] <strong>真实链路</strong> 和 <strong>模拟延迟</strong> 两种方式都能出提示。</li><li>[ ] 四档提示难度切换正常。</li><li>[ ] 复盘报告可以导出。</li></ul><h2 id="语言与错误" tabindex="-1">语言与错误 <a class="header-anchor" href="#语言与错误" aria-label="Permalink to &quot;语言与错误&quot;">​</a></h2><ul><li>[ ] 在设置中切换 English / 简体中文，面板、托盘菜单、错误信息和练习报告即时切换。</li><li>[ ] 故意填错一个密钥，错误提示带错误码；点击 <strong>查看解决办法</strong> 打开当前语言的文档并定位到该错误码。</li><li>[ ] 诊断压缩包里没有任何密钥。</li></ul><h2 id="升级与文档" tabindex="-1">升级与文档 <a class="header-anchor" href="#升级与文档" aria-label="Permalink to &quot;升级与文档&quot;">​</a></h2><ul><li>[ ] 执行 <code>scoop update meetcue</code> 后，设置、密钥、延迟历史和练习记录都还在。</li><li>[ ] 文档站点在手机和电脑上都便于阅读；切换语言后停留在对应页面；搜索中文关键词能找到结果。</li></ul>',17)])])}const _=a(o,[["render",r]]);export{m as __pageData,_ as default};
